// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;

    function setUp() public { c = new MyContract(); }

    // fuzz the amount and the sender (actor) that funds and invokes sendTo
    function testFuzz_property(uint256 amount, address actor) public {
        // keep amount in a reasonable bound so vm.deal can fund actor and value fits in balance
        amount = bound(amount, 0, 1 ether);
        // ensure actor is not the zero address (vm.prank with address(0) is allowed but avoid weirdness)
        vm.assume(actor != address(0));

        // Deploy a callee that will revert on receiving funds to distinguish checked transfer from unchecked call
        Reverter rev = new Reverter();

        // fund the actor so they can call sendTo with value
        vm.deal(actor, amount);

        // actor must be the owner of c to pass the require(msg.sender == owner)
        // The constructor set owner = msg.sender, which is the test contract deployer (address(this)).
        // So we need to call sendTo as that owner. Use vm.prank to impersonate the owner and send value.
        // We use actor only to fund the callee (not as msg.sender). To exercise fuzzed actor, we let actor be the recipient of funds in case that matters to external behavior (but here receiver is the reverting contract).

        // Call as the owner (the test contract created c, so address(this) is owner)
        bool ok;
        try c.sendTo(address(rev), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: when the recipient reverts on receiving value, the reference implementation (which uses transfer)
        // will revert so ok == false for ALL inputs; the mutant (which uses unchecked low-level call) will return ok == true for SOME inputs.
        // We assert the property that the reference always reverts: ok must be false.
        assertTrue(!ok);
    }
}

// adversarial helper that ALWAYS reverts on receiving funds
contract Reverter {
    receive() external payable {
        revert("revert on receive");
    }
}
